* BRICKS CHAT -- Model 4 (43x80) layout.
*
* Same field-name contract as chatm2.map -- only the history depth and
* the bottom-strip row coordinates differ. See chatm2.map for the
* colour rationale and the col-0 / LEN-78 layout choice.
MAP CHATM4 SIZE 43x80
  FIELD TITLE  AT 0,0  LEN 12 PROT BRIGHT COLOR=RED       "BRICKS CHAT"
  FIELD CLOCK  AT 0,36 LEN 8  PROT COLOR=TURQUOISE
  FIELD TOPIC  AT 0,50 LEN 28 PROT COLOR=YELLOW
  FIELD ROW01  AT 2,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW02  AT 3,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW03  AT 4,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW04  AT 5,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW05  AT 6,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW06  AT 7,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW07  AT 8,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW08  AT 9,0  LEN 78 PROT COLOR=GREEN
  FIELD ROW09  AT 10,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW10  AT 11,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW11  AT 12,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW12  AT 13,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW13  AT 14,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW14  AT 15,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW15  AT 16,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW16  AT 17,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW17  AT 18,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW18  AT 19,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW19  AT 20,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW20  AT 21,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW21  AT 22,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW22  AT 23,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW23  AT 24,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW24  AT 25,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW25  AT 26,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW26  AT 27,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW27  AT 28,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW28  AT 29,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW29  AT 30,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW30  AT 31,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW31  AT 32,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW32  AT 33,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW33  AT 34,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW34  AT 35,0 LEN 78 PROT COLOR=GREEN
  FIELD ROW35  AT 36,0 LEN 78 PROT COLOR=GREEN
  FIELD STATUS AT 39,0 LEN 78 PROT COLOR=RED
  FIELD PROMPT AT 40,0 LEN 3  PROT BRIGHT COLOR=GREEN     "==>"
  INPUT INPUT  AT 40,10 LEN 62 UNDERSCORE COLOR=WHITE
  STOP         AT 40,75
  FIELD FOOTER AT 42,0 LEN 36 PROT COLOR=BLUE             "F3=exit  Enter=send"
  CURSOR AT INPUT
ENDMAP
